  "certified_type": {
    "category": "Non-automatic weighing instrument",
    "type_designations": ["M2400-P03"],
    "module_designation": "Non-automatic weighing instrument",
    "description": "Built-for-purpose class III self-indicating electronic weighing instrument with single-interval indication or dual or triple weighing ranges. Consists of an electronic indicator module, type M2400-P03, connected to one or two separate and suitable load receptor module(s). It has the possibility to perform price calculation, but it may not be used for direct sale to the public. The name of the instrument may be followed by alphanumeric characters for technical, legal or commercial characterization."
  },
  "components": [
    {
      "role": "electronic indicator module",
      "type_designations": ["M2400-P03"],
      "characteristics": {
        "type_level": {
          "fractional_factor_pi": {"value": 0.5, "unit_symbol": null, "unit_id": null},
          "minimum_input_voltage_per_vsi": {"value": 0.25, "unit_symbol": "μV", "unit_id": null},
          "excitation_voltage": {"value": 3, "unit_symbol": "V", "unit_id": null},
          "excitation_voltage_type": {"value": "DC, bipolar"},
          "excitation_voltage_effective": {"value": 6, "unit_symbol": "V", "unit_id": null},
          "circuit_for_remote_sense": {"value": "present on the model with 6-terminal connector", "unit_symbol": null, "unit_id": null},
          "minimum_input_impedance": {"value": 87, "unit_symbol": "Ω", "unit_id": null},
          "maximum_input_impedance": {"value": 1100, "unit_symbol": "Ω", "unit_id": null}
        }
      }
    },
    {
      "role": "load receptor module (platforms, weighbridge platforms, bin/tank/hopper assemblies)",
      "type_designations": ["PU8000", "PU9000", "PU9010"],
      "characteristics": {
        "type_level": {
          "construction": {"value": "all-steel or steel-reinforced concrete construction, surface or pit mounted; U-shaped platforms all steel, surface mounted", "unit_symbol": null, "unit_id": null},
          "reduction_ratio": {"value": 1, "unit_symbol": null, "unit_id": null},
          "junction_box_location": {"value": "mounted in or on the platform (platforms/weighbridges); mounted on dead structure (bin, tank, hopper); mounted in the platform (U-shaped platforms)", "unit_symbol": null, "unit_id": null},
          "load_cells": {"value": "any R60-certified load cell (generic receptors); 4 pcs Vishay Tedea-Huntleigh Model 3510 or 4 pcs Flintec type SLB or type SB14 (U-shaped platforms)", "unit_symbol": null, "unit_id": null},
          "movable_platforms_equipment": {"value": "shall be equipped with level indicators or tilt switches", "unit_symbol": null, "unit_id": null}
        }
      }
    },
    {
      "role": "load cell (general acceptance)",
      "alternatives": null,
      "characteristics": {
        "type_level": {
          "acceptance_condition": {"value": "OIML R60:2000 or R60:2017 Certificate of Conformity required; compatibility of modules per OIML R76:2006 Annex F; NH-marked load cells allowed only if humidity testing to OIML R76:2006 has been conducted", "unit_symbol": null, "unit_id": null}
        }
      }
    },
    {
      "role": "load cell (U-shaped platforms, 4 pcs per platform)",
      "type_designations": ["Vishay Tedea-Huntleigh Model 3510", "Flintec SLB", "Flintec SB14"],
      "alternatives": "OR",
      "characteristics": {
        "type_level": {
          "quantity_per_platform": {"value": 4, "unit_symbol": null, "unit_id": null}
        }
      }
    }
  ],
  "characteristics": {
    "type_level": {
      "accuracy_class": {"value": "III and IIII", "unit_symbol": null, "unit_id": null},
      "load_cell_inputs": {"value": 2, "unit_symbol": null, "unit_id": null},
      "weighing_ranges": {"value": "single-interval or multi-range (up to 3 ranges)", "unit_symbol": null, "unit_id": null},
      "maximum_capacity": {"value": {"min": 0.3, "max": 300000}, "unit_symbol": "kg", "unit_id": null},
