      "maximum_tare_effect": {"value": "-Max", "unit_symbol": null, "unit_id": null},
      "power_supply_voltage_ac": {"value": {"min": 110, "max": 230}, "unit_symbol": "V", "unit_id": null},
      "power_supply_frequency": {"value": {"min": 50, "max": 60}, "unit_symbol": "Hz", "unit_id": null},
      "power_supply_voltage_dc": {"value": {"min": 12, "max": 24}, "unit_symbol": "V", "unit_id": null},
      "operational_temperature": {"value": {"min": -10, "max": 40}, "unit_symbol": "°C", "unit_id": null},
      "electromagnetic_class": {"value": "E2", "unit_symbol": null, "unit_id": null},
      "initial_zero_setting_range": {"value": {"min": null, "max": 20}, "unit_symbol": "%", "unit_id": null},
      "zero_tracking_range": {"value": {"min": null, "max": 4}, "unit_symbol": "%", "unit_id": null},
      "devices": {"value": "initial zero setting device; combined semi-automatic zero setting and tare balancing device; zero tracking; automatic tare device; preset tare device; price calculation device; data storage device; printing device; gravity compensation device; internal alibi storage device; stable equilibrium, zero, net and active range indicators", "unit_symbol": null, "unit_id": null},
      "interfaces": {"value": "2 x RS-232, 2 x USB, Ethernet, 4 x digital input/outputs, CAN bus", "unit_symbol": null, "unit_id": null},
      "peripheral_interface_protection": {"value": "protective", "unit_symbol": null, "unit_id": null},
      "firmware_version": {"value": "1.00-20 or higher (up to 1.99-99)", "unit_symbol": null, "unit_id": null},
      "weighing_module_version": {"value": "100", "unit_symbol": null, "unit_id": null}
    },
    "config_level": [
      {
        "attribute": "max_number_of_verification_scale_intervals",
        "axis": "accuracy_class",
        "values": [
          {"condition": "III", "value": {"min": null, "max": 10000}, "unit_symbol": null, "unit_id": null},
          {"condition": "IIII", "value": {"min": null, "max": 1000}, "unit_symbol": null, "unit_id": null}
        ]
      },
      {
        "attribute": "maximum_cable_length_indicator_to_junction_box",
        "axis": "wiring_system",
        "values": [
          {"condition": "4-wire (no sense), shielded", "value": "certified length of the load cell cable, connected directly to the indicator", "unit_symbol": null, "unit_id": null},
          {"condition": "6-wire (sense), shielded", "value": {"min": null, "max": 1077}, "unit_symbol": "m/mm²", "unit_id": null}
        ]
      },
      {
        "attribute": "maximum_resistance_per_wire",
        "axis": "wiring_system",
        "values": [
          {"condition": "6-wire (sense), shielded", "value": 18.2, "unit_symbol": "Ω", "unit_id": null}
        ]
      }
    ]
  },
  "matrix_tables": [
    {
      "name": "U-shaped platform capacity variants (PU8000, PU9000, PU9010)",
      "columns": ["platform", "max_1", "e_1", "max_2", "e_2", "load_cell_emax"],
